SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(8*10^9);Alarm(1500);tt:=Cputime();root:="work/deg10/continuation_20261031b/M3N18/";AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");Attach("work/deg10/continuation_20261029/deps/fast_hecke_11.m");Attach(root cat "inputs/fast_full_aut_hash_m3_18_root.m");Attach(root cat "isogenies_witness.m");
k:=GF(13);X:=MDX11(3,18,k);C:=Curve(X);FF:=FunctionField(C);F,mp:=AlgorithmicFunctionField(FF);assert Genus(F)eq 10;B:=BaseField(F);O:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);
function ER(f)return [[Integers()!c:c in Coefficients(Numerator(f))],[Integers()!c:c in Coefficients(Denominator(f))]];end function;
function EF(f)return [ER(c):c in Eltseq(F!f)];end function;
function PD(P)a,b:=TwoGenerators(P);assert ideal<Order(Ideal(P))|a,b>eq Ideal(P);return[*Degree(P),IsFinite(P)select 1 else 0,[EF(a),EF(b)]*];end function;
function PlacePair(qt)cp:=MDPlaceCommonZeros(X`_coordinates,qt);ps,es:=Support(FunctionFieldDivisor(Divisor(cp)));assert #ps eq 1 and es eq[1];P:=ps[1];K:=Parent(qt[1]);assert M3EighteenRootKey([Evaluate(f,cp):f in X`_coordinates],K,13,Degree(K))eq M3EighteenRootKey(qt,K,13,Degree(K));return P;end function;
function FX(vals)L:=Parent(vals[1]);theta:=PrimitiveElement(L);d:=Degree(L,k);M:=Matrix(k,[Eltseq(theta^i,k):i in[0..d-1]]);assert Rank(M)eq d;co:=[Eltseq(Solution(M,Vector(k,Eltseq(v,k)))):v in vals];return[*[Integers()!a:a in Coefficients(MinimalPolynomial(theta,k))],[[Integers()!a:a in c]:c in co]*];end function;
inputs:=eval Read(root cat "paired_final_Hecke_inputs_v2.m");out:=[* *];q:=7;RK:=PolynomialRing(k);
for row in inputs do if (row[1]-1)mod 3 ne shard then continue;end if;D:=DivisorGroup(F)!0;rs:=[* *];for inp in row[3]do d:=inp[1];K<z>:=ext<k|RK!inp[2]>;qt:=[Evaluate(RK!v,z):v in inp[3]];q0,t0:=Explode(qt);E:=EllipticCurve([q0*t0-q0+t0+2,K!0,q0*t0^2-q0*t0+t0,K!0,K!0]);P:=E![0,0];Q:=E![-t0,t0^2];assert 3*P eq E!0 and 18*Q eq E!0 and 9*Q ne E!0 and 6*Q ne E!0;assert WeilPairing(P,6*Q,3)ne 1;N:=PlacePair(qt);assert Degree(N)eq d;src:=FX(qt cat aInvariants(E)cat[P[1],P[2],Q[1],Q[2]]);dq:=M3EighteenRootNormalizedPair(E,q*P,q*Q);Nd:=PlacePair(dq);assert Degree(Nd)eq d;D-:=Divisor(N)+q*Divisor(Nd);trs:=[* *];for tr in MD318IsogeniesWitness(E,[P,Q],q)do EG,ps,e,EL,ker:=Explode(tr);vv:=M3EighteenRootNormalizedPair(EG,ps[1],ps[2]);Nt:=PlacePair(vv);mult:=e*d/Degree(Nt);assert Denominator(mult)eq 1;mult:=Integers()!mult;D+:=mult*Divisor(Nt);LL:=BaseRing(EG);wvals:=vv cat aInvariants(EL)cat[LL!P[1],LL!P[2],LL!Q[1],LL!Q[2]]cat aInvariants(EG)cat[ps[1][1],ps[1][2],ps[2][1],ps[2][2]]cat Coefficients(ker);Append(~trs,[*PD(Nt),mult,e,FX(wvals)*]);end for;assert &+[r[2]*r[1][1]:r in trs]eq(q+1)*d;Append(~rs,[*PD(N),src,PD(Nd),FX(dq),trs*]);end for;assert Degree(D)eq 0;h0:=#Basis(D:Reduction:=false,Simplification:="None");Append(~out,[*row[1],row[2],q,rs,h0*]);Write(root cat "final_Hecke7_v2_s"cat IntegerToString(shard)cat".m",Sprint([*[ER(c):c in Coefficients(DefiningPolynomial(F))],[EF(mp(f)):f in X`_coordinates],out*]):Overwrite:=true);print "M318_FINAL_HECKE",row[1],row[2],h0,Cputime(tt);end for;print "D31B_M318_FINAL_HECKE_COMPLETE",shard,#out,[r[1]:r in out|r[5]ne 0],Cputime(tt);quit;
